mapper.update:
update sdsorder.u_p_receivedetail_${tableSuffix}
   set inventorydetailcode = #{inventoryDetailCode},
       goodqty = coalesce(actualqty, 0),
       badqty = greatest(qty - coalesce(actualqty, 0), 0),
       qualitystatus = #{qualityStatus},
       updatetime = sysdate()
 where shop_code = #{shopCode}
   and detailcode = #{detailCode}
   and inventorydetailcode is null

update sdsorder.u_p_receivedetail_${tableSuffix}
   set inventorydetailcode = #{inventoryDocCode},
       goodqty = 0,
       badqty = qty,
       qualitystatus = '短装',
       updatetime = sysdate()
 where shop_code = #{shopCode}
   and detailcode = #{detailCode}
   and inventorydetailcode is null

update sdsorder.u_p_receivedetail_${tableSuffix}
   set actualqty = null, batchcode = null, serialnumbers = null,
       inventorydoccode = null, goodqty = 0, badqty = 0, qualitystatus = null,
       updatetime = sysdate()
 where shop_code = #{shopCode}
   and inventorydoccode = #{inventoryDocCode}
   and inventorydetailcode is null

mapper.select:
select coalesce(sum(d.qty), 0)
  from sdsorder.u_p_receivedetail_${tableSuffix} d
 where d.shop_code = #{shopCode}
   and d.purchasedetailcode = #{purchaseDetailCode}
   and d.inventorydetailcode is null

   and d.receivecode != #{excludeReceiveCode}
